REVOKE EXECUTE ON FUNCTION public.live_tracking_identity(uuid), public.live_tracking_identity_v2(uuid), public.live_tracking_sos_flags(uuid), public.live_tracking_sos_flags_guard() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.live_tracking_identity(uuid), public.live_tracking_identity_v2(uuid), public.live_tracking_sos_flags(uuid) TO service_role;
REVOKE ALL ON public.tracking_points, public.tracking_sos, public.entrants, public.event_entrants, public.profiles, public.push_subscriptions FROM anon;
DROP POLICY IF EXISTS "crew read entrants" ON public.entrants;
DROP POLICY IF EXISTS "crew read event_entrants" ON public.event_entrants;
DROP POLICY IF EXISTS "Anyone can submit feedback" ON public.feedback;
REVOKE INSERT ON public.feedback FROM anon, authenticated;
GRANT INSERT ON public.feedback TO service_role;
DROP POLICY IF EXISTS "Site settings are viewable by everyone" ON public.site_settings;
CREATE POLICY "Public presentation settings only" ON public.site_settings FOR SELECT TO anon, authenticated USING (key IN ('branding','loyalty','quick_links','support','waivers') OR key LIKE 'class_availability:%' OR private.is_admin());
CREATE OR REPLACE FUNCTION private.results_visible(_event_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.events e WHERE e.id=_event_id AND private.event_visible(e.id) AND (e.results_published OR private.is_admin())); $$;
REVOKE ALL ON FUNCTION private.results_visible(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.results_visible(uuid) TO anon, authenticated, service_role;
DROP POLICY IF EXISTS "public read results" ON public.event_results;
CREATE POLICY "Published visible results" ON public.event_results FOR SELECT TO anon, authenticated USING (private.results_visible(event_id));
DROP POLICY IF EXISTS "public read result sets" ON public.event_result_sets;
CREATE POLICY "Published visible result sets" ON public.event_result_sets FOR SELECT TO anon, authenticated USING (private.results_visible(event_id));
DROP POLICY IF EXISTS "Riders add their own tracking points" ON public.tracking_points;
CREATE POLICY "Owned event tracking points" ON public.tracking_points FOR INSERT TO authenticated WITH CHECK (auth.uid()=user_id AND (entrant_id IS NULL OR EXISTS (SELECT 1 FROM public.entrants e WHERE e.id=entrant_id AND e.user_id=auth.uid())) AND private.event_visible(event_id) AND (private.is_admin() OR private.is_crew() OR EXISTS (SELECT 1 FROM public.event_entrants ee JOIN public.entrants e ON e.id=ee.entrant_id WHERE ee.event_id=tracking_points.event_id AND e.user_id=auth.uid())));
DROP POLICY IF EXISTS "Riders create their own SOS alerts" ON public.tracking_sos;
CREATE POLICY "Owned event SOS alerts" ON public.tracking_sos FOR INSERT TO authenticated WITH CHECK (auth.uid()=user_id AND private.event_visible(event_id) AND (private.is_admin() OR private.is_crew() OR EXISTS (SELECT 1 FROM public.event_entrants ee JOIN public.entrants e ON e.id=ee.entrant_id WHERE ee.event_id=tracking_sos.event_id AND e.user_id=auth.uid())));
CREATE OR REPLACE FUNCTION public.guard_push_subscription_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.user_id IS DISTINCT FROM NEW.user_id THEN RAISE EXCEPTION 'Subscription belongs to another account'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_push_subscription_owner() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER push_subscription_owner_guard BEFORE UPDATE ON public.push_subscriptions FOR EACH ROW EXECUTE FUNCTION public.guard_push_subscription_owner();